export default [{"id":2431,"question":"ما رأيكم في حديث لا تشتروا السمك في الماء...؟","title":"ما صحة حديث \"لا تشتروا السمك في الماء\"؟","answer":"الجواب:\nما له أصل، إلا إذا عرف إذا لم يتيسر شراؤه، أما إذا كان في ماء محصور في بركة ما يضر، أما إذا كان في البحر لا يبيعه؛ غرر، لا يدري يحصّله وإلا ما يحصّله.","link":"https://binbaz.org.sa/fatwas/22559/ما-صحة-حديث-لا-تشتروا-السمك-في-الماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث لا تشتروا السمك في الماء..mp3","categories":["شروح الحديث","الحكم على الأحاديث","فتاوى متنوعة","البيوع"]},{"id":4751,"question":"البدع التي تكون في الجنِّ يتلقونها عن الإنس، أو عندهم مُبتدعة تلقَّى بعضُهم عن بعضٍ؟","title":"هل لدى الجن المسلمين بدعٌ؟ ومن أين تلقوها؟","answer":"الذي يظهر -والله أعلم- أنَّ منهم مَن يتلقاها عن الإنس، ومنهم مَن يتلقاها عن الجنِّ؛ لأنهم لهم اتِّصالًا بالإنس، ولهم معرفة بأحوال الإنس، يعلمون بالمجالس، ويقرؤون ويكتبون، فلا مانعَ أن يأخذوا عن الإنس بعض الخير والشرِّ، وعن بعضهم مثل الإنس.","link":"https://binbaz.org.sa/fatwas/25094/هل-لدى-الجن-المسلمين-بدع-ومن-اين-تلقوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل عند الجن المسلمين بدعٌ، ومن أين تلقوها.mp3","categories":["البدع والمحدثات","فتاوى متنوعة"]},{"id":4752,"question":"الحكايات والأخبار التي تُروى في مشاهدة بعض الناس لشيءٍ من النَّعيم؟","title":"ما صحة الأخبار في رؤية نعيم القبر أو أهواله؟","answer":"هذا واقع، ذكره ابنُ رجبٍ رحمه الله وغيره، ذكره ابنُ رجب في \"أهوال القبور\"، والقرطبي في \"التذكرة\"، والسَّفاريني في \"البحور الزاخرة\"، وغيرهم ذكروا أشياء من هذا كثيرة، ابن رجب ذكر من هذا أشياء في \"أهوال القبور\"، أطلع الله الناس على ما يشاء ؛ عبرةً، للعظة والتَّذكر، مثلما أطلع اللهُ نبيَّه ﷺ على القبرين، قال: إنهما ليُعذَّبان، وما يُعذَّبان في كبيرٍ، أما أحدهما فكان لا يستتر من بوله، وأما الآخر فكان يمشي بالنَّميمة، هذا مما أطلع عليه النبيَّ ﷺ، وفي غلام -مولاه كركرة- قال: إنَّ الشَّملة التي غلَّها لتشتعل عليه نارًا، وأشياء من هذا جاءت عن النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/25096/ما-صحة-الاخبار-في-روية-نعيم-القبر-او-اهواله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأخبار التي تُروى في مشاهدة بعض الناس لشيءٍ من نعيم القبر أو أهواله.mp3","categories":["شروح الحديث","الحكم على الأحاديث","فتاوى متنوعة","البيوع"]},{"id":4757,"question":"كيف نُفرق بين المعجزة والكرامات؟","title":"ما الفرق بين المعجزات والكرامات؟","answer":"الأصل فيها أنها واحد، الكرامة والمعجزة هي الخارق للعادة، فإذا كان من باب التَّحدي كما جاءت به الرسل فهذه يُقال لها: معجزات في الاصطلاح، وتُسمَّى: كرامات في المعنى أيضًا. وإن كانت على يد المؤمنين وليسوا ممن ادَّعى الرسالةَ، بل هم من أتباع الرسل، فهذه أخص باسم الكرامة، وهي معجزة أيضًا للنبي الذي جاء بما عليه هذا المؤمن. فإن كانت ليست مع الأنبياء ولا مع المؤمنين؛ فهي من الشَّعاوذ التي تأتي بها الشياطين، وإن سُميت: خارقًا، لكنَّها في الحقيقة شعوذة من الشيطان، وتزيين من الشيطان وتلبيس؛ حتى يظنَّ الناسُ أنَّ هذا مؤمن، أو أنَّ هذا نبي، وليس كذلك.\nولهذا قال العلماء كما تقدم: الميزان التزامه بالشرع، مَن كان مُلتزمًا بالشرع مُستقيمًا عليه ظاهرًا وباطنًا؛ فما وقع له من الخوارق فهو كرامة، وإن كان غير ملتزمٍ فإنه مما تأتي به الشَّياطين من الخوارق لأربابها؛ للتلبيس على الناس، أو لقضاء حوائج أوليائهم من الإنس، كما قد يفعل السَّحرة والكهان والمنجمون؛ تلبيسًا من الشياطين وتغريرًا بهؤلاء.","link":"https://binbaz.org.sa/fatwas/25111/ما-الفرق-بين-المعجزات-والكرامات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الفرق بين المعجزات والكرامات.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5237,"question":"أقدم على فعل معصيةٍ ثم أقول: تبتُ إلى الله، وهكذا كلما فعلتُ معصيةً تبتُ،  والآن ولله الحمد ما عدتُ إلى المعصية مرةً أخرى، فيا فضيلة الشيخ هل عليَّ شيء أفعله بعد التوبة من هذه المعصية؟ وهل سيتقبّل الله توبتي؟","title":"ما دواء المعاصي وتكرارها؟","answer":"الجواب: دواء المعاصي التوبة، ولو تكررت، ما دام يصدق في التوبة، يقولها تائبًا، صادقًا، نادمًا، مُقلعًا منها، عازمًا ألا يعود، ثم يُبتلى بها بعد شهرٍ أو شهرين أو سنةٍ أو سنتين؛ عليه توبةٌ أخرى، والتوبة الأولى وقعت في محلِّها، وكفاه الله شرَّ الذنب الأول، كل توبةٍ تمحو ما قبلها من الذنب إذا كانت صادقةً. أما إذا قالها باللسان: \"تبتُ إلى الله\" باللسان وهو كاذبٌ ومُصرٌّ على المعصية متى وجدها فعلها، ما هذه توبة، التوبة ليست هكذا، الله يقول جلَّ وعلا: وَلَمْ يُصِرُّوا عَلَى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ [آل عمران:135]، لا بد من عدم الإصرار، فالتائب لا بد أن تشتمل توبته على أمورٍ ثلاثة: النَّدم على الماضي من المعصية، والإقلاع منها وتركها، والثالث العزيمة ألا يعود فيها، هذه توبة الصادق، تشتمل على هذه الأمور: أولًا: أن يُقلع منها ويتركها ويحذرها. ثانيًا: يندم على ما مضى منها. ثالثًا: يعزم عزمًا صادقًا ألا يعود فيها. فإذا تمَّت التوبةُ على هذه الأركان؛ محا الله بها الذنب. وإن كان الذنبُ يتعلق بالمخلوق فلا بدّ من ردِّ حقِّ المخلوق، إذا كانت المعصية تتعلق بحقِّ المخلوق من سرقةٍ، مثل: غصب مالٍ، فلا بدّ من شرطٍ رابعٍ: أن يرد المال على صاحبه، أو يستحلّه منه، متى سرق مالًا أو غصب مالًا أو ضرب إنسانًا لا بد من استحلاله، ما تتم توبته إلا بهذا النَّدم على الماضي، والعزيمة ألا يعود، والإقلاع من ذلك، ثم استسماح صاحب الحقِّ، أو ردّ الحق عليه: سرق من إنسانٍ مئة ريـال، ألف ريـال، أكثر، ما تتم توبته إلا بردِّها إلى صاحبها، غصبها منه، نهبها منه، يردها أو يستسمحه. هكذا إذا كان الذنبُ قتلًا لا بدّ من أداء القصاص أو الدية أو سماح أهل الحق، إما أن يسمحوا بالقصاص فيؤدوا القصاص، أو بالدية ويُؤدوا الدية، أو يسمحوا عن الجميع؛ فيسلم من ذلك. فالمقصود لا بد في التوبة من ردِّ حقِّ المخلوق، أو استسماحه وسماحه.","link":"https://binbaz.org.sa/fatwas/30581/ما-دواء-المعاصي-وتكرارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 344.mp3","categories":["فتاوى متنوعة","الرقائق"]},{"id":5352,"question":"هناك مَن يقول أنَّ من الرافضة مَن بدعته مُكفرة، ومَن بدعته مُفسقة، هذا تقسيمٌ صحيحٌ؟","title":"هل بدعة الرافضة مُكفِّرة أم مُفسِّقة؟","answer":"الجواب: الرافضة أقسام، ذكر الشَّهرستاني أنهم اثنان وعشرون قسمًا، الرافضة أقسام كثيرة، الشيعة، لكن الرافضة الإمامية يغلون في عليٍّ وفي أهل البيت، ويقولون: يعلم الغيب، ويعبدونهم، هؤلاء كفَّار. لكن بعض الشيعة دون ذلك: الذين يُفضلون عليًّا على عثمان، أو على الصديق وعمر، هؤلاء مُبتدعة، لا يكفرون بهذا، كذلك منهم الزيدية، من أقسام الشيعة وفرق الشيعة: يُفضلون عليًّا على عثمان. س: ومَن يُكفِّرهم يُكفِّرهم بأعيانهم أو بالنوع؟ ج: مَن عُرف بعينه أنه يدَّعي علم الغيب، أو يغلو في آل البيت؛ هو كافر بعينه، من جنس مَن عبد عليًّا أو غيره يكون كافرًا، أو زعم أنه يعلم الغيب يكون كافرًا.[1]","link":"https://binbaz.org.sa/fatwas/31052/هل-بدعة-الرافضة-مكفرة-ام-مفسقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 008.mp3","categories":["البدع والمحدثات","فتاوى متنوعة"]},{"id":5375,"question":"في الإسراء أعيدت أجساد الأنبياء؟","title":"هل أُعيدت أجساد الأنبياء في ليلة الإسراء؟","answer":"الجواب: قاموا، مثَّلهم الله بالسَّماوات بأجسادهم أحياء، ثمانية: آدم وعيسى ويحيى ويوسف وإدريس وموسى وهارون وإبراهيم عليهم الصلاة والسلام، رآهم على صفتهم، سلَّموا عليه وكلَّمهم، ولا يمنع هذا موتهم، إلا عيسى فلم يمت، عيسى حتى الآن لم يمت، يموت في آخر الزمان، ينزل إلى الأرض ويحكم بشريعة محمدٍ ثم يموت عند خروج الدَّجال.[1]","link":"https://binbaz.org.sa/fatwas/31109/هل-اعيدت-اجساد-الانبياء-في-ليلة-الاسراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/dorar_saniya_najdiya005.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5385,"question":"هل الصبر له مراتب أم مرتبة واحدة؟","title":"ما مراتب الصبر؟ وهل يكفي باللسان؟","answer":"الجواب: مبيّنة، ثلاث مراتب: الصبر على المصائب بقلبه ولسانه وجوارحه جميعًا، ثلاث:  بقلبه لا يجزع ولا يتسخَّط. وبلسانه لا يتكلم بما لا ينبغي من: النِّياحة والسَّب والكلام السيئ. وبجوارحه لا يخمش وجهًا، ولا يشق ثوبًا، ولا يلطم خدًّا، ولا يحثو على نفسه التراب، وأشباه ذلك. س: مَن شكر بلسانه وخالف ذلك بجوارحه؟ ج: يكون ما صبر.[1]","link":"https://binbaz.org.sa/fatwas/31125/ما-مراتب-الصبر-وهل-يكفي-باللسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 001.mp3","categories":["الرقائق","فتاوى متنوعة"]},{"id":5386,"question":"مداخل الشيطان الثلاثة السالفة الذكر عليها دليل؟","title":"ما مداخل الشيطان الثلاثة؟ وما أدلتها؟","answer":"الجواب: من القرآن، إذا تأمَّلتَ: الغضب: معلوم أنَّه من أسباب الشيطان، ولما غضب موسى ألقى الألواح، وفيها كلام الرب . والغفلة: مثل ما قال الله جل وعلا: وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِنَ الْجِنِّ وَالإِنسِ لَهُمْ قُلُوبٌ لا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لا يُبْصِرُونَ بِهَا وَلَهُمْ آذَانٌ لا يَسْمَعُونَ بِهَا أُوْلَئِكَ كَالأَنْعَامِ بَلْ هُمْ أَضَلُّ أُوْلَئِكَ هُمُ الْغَافِلُونَ [الأعراف:179]، وقال تعالى: وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهُوَ لَهُ قَرِينٌ [الزخرف:36] يعني: ومَن يغفل. وأمَّا الشهوة : فأدلتها كثيرة -نسأل الله العافية- قال جل وعلا في كتابه الكريم: إِنْ يَتَّبِعُونَ إِلَّا الظَّنَّ وَمَا تَهْوَى الأَنْفُسُ [النجم:23]، وقال تعالى: فَإِنْ لَمْ يَسْتَجِيبُوا لَكَ فَاعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَاءَهُمْ (الشهوات) وَمَنْ أَضَلُّ مِمَّنِ اتَّبَعَ هَوَاهُ بِغَيْرِ هُدًى مِنَ اللَّهِ [القصص:50]، نسأل الله العافية، وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِ وَنَهَى النَّفْسَ عَنِ الْهَوَى ۝ فَإِنَّ الْجَنَّةَ هِيَ الْمَأْوَى [النازعات:40، 41].[1]","link":"https://binbaz.org.sa/fatwas/31126/ما-مداخل-الشيطان-الثلاثة-وما-ادلتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 002.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5387,"question":"لعن الشيطان؟","title":"ما حكم لعن الشيطان؟ وهل التعوُّذ أفضل؟","answer":"الجواب: جائز كما لعنه الله، لكن التَّعوذ بالله من شرِّه أحسن؛ لأنه عند اللعن قد يتعاظم كما جاء في الحديث، لكن عند التعوُّذ بالله من شرِّه يتصاغر. س: الحديث صحيح؟ ج: لا بأس به: لا تقُلْ: تَعِسَ الشيطانُ، بل قُلْ: بسم الله، المقصود أن التعوُّذ بالله من شرِّه أفضل من لعنه، والله لعنه وطرده. س: حديث: لا تلعنوا الشيطان واستعيذوا منه؟ ج: ما أعرفه. س: قصة آدم عليه السلام مع الشيطان: فَلَمَّا آتَاهُمَا صَالِحًا جَعَلَا لَهُ شُرَكَاءَ [الأعراف:190]، صحيحة؟ ج: نص القرآن أنه مع آدم؛ لأن الله قال: هُوَ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا فَلَمَّا تَغَشَّاهَا ... الآية [الأعراف:189]، فالقصة قصة آدم مع زوجته، وقال بعض السلف أن المراد به الذرية، ولكن نص القرآن واضح.[1]","link":"https://binbaz.org.sa/fatwas/31127/ما-حكم-لعن-الشيطان-وهل-التعوذ-افضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 003.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5389,"question":"يقول: (لا طريق إلى الله تعالى أقرب من العبودية، ولا حجابَ أغلظ من الدَّعوى) ما الدعوى؟","title":"ما معنى عبارة \"لا حجابَ أغلظ من الدَّعوى\"؟","answer":"الجواب: العبودية: الانكسار بين يدي الله وطاعته. والدَّعوى: كونه يدَّعي أنه كذا، وأنه كذا، ويمُنُّ بأعماله بأنه تقيّ، وأنه يقوم الليل، وأنه صوَّام، فيُبتلى بالرياء، ويُبتلى بالمنَّة على الله.[1]","link":"https://binbaz.org.sa/fatwas/31128/ما-معنى-عبارة-لا-حجاب-اغلظ-من-الدعوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 004.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5391,"question":"إذا أصرَّ على الكبائر هل تُكفَّر السيئاتُ الصَّغائر؟","title":"هل تُكفَّرُ الصَّغائرُ للمصرِّ على كبيرة؟","answer":"الجواب: مثل ما قال ربك: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ [النساء:31] يعني: الصغائر، فضل من الله. لكن اختلف الناس في حدِّ الكبيرة، قد يظنها صغيرةً وهي كبيرة، فليحذر السّيئات كلها، صغيرها وكبيرها، يكون عنده حذر؛ لأنه قد يقع في الكبيرة ويحسب أنها صغيرة. س: ما دام مُصِرًّا على كبيرةٍ وصلَّى الصلوات هل تُكفَّر عنه الصَّغائر؟ ج: لا، ما تُكفَّر، الشرط اجتناب الكبائر.[1]","link":"https://binbaz.org.sa/fatwas/31134/هل-تكفر-الصغاىر-للمصر-على-كبيرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 007.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5422,"question":"التعصب لمذاهب أو لأشخاص أو لجماعات، هل يُعتبر من عبادة غير الله؟","title":"حكم التعصب للمذاهب والأشخاص والجماعات؟","answer":"الجواب: لا، هذا منكر لا يجوز. س: ما يعتبر من عبادة غير الله؟ ج: هذا إذا استحلَّه، إذا استحلَّه وأن متبوعه معصومٌ وما قاله حقّ؛ فهذا يدخل في الردة، أمَّا عموم التقليد ففيه تفصيل. س: يقول بعضُهم: \"كلّ ما خالف نصَّ الإمام يُؤول\"؟ ج: هذا غلط، يُنكر عليه ولا بُدَّ، فتراجع النصوص وتُقدَّم النصوص.[1]","link":"https://binbaz.org.sa/fatwas/31209/حكم-التعصب-للمذاهب-والاشخاص-والجماعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 047.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5425,"question":"الأطفال الذين رأوا النبيَّ ﷺ، كالطفل الذي رفعته أمُّه الخثعمية، هل هؤلاء صحابة؟","title":"هل الطفل الذي رأى النبي يُعَدُّ صحابيًا؟","answer":"الجواب: الذي رأى النبيَّ وهو مؤمنٌ تَبَعٌ لأهله: صحابي، رآه النبيُّ ﷺ أو قُدِّم للنبي فحنَّكه. س: ما يُشترط البلوغ؟ ج: لا، ما يُشترط.[1]","link":"https://binbaz.org.sa/fatwas/31206/هل-الطفل-الذي-راى-النبي-يعد-صحابيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 044.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5444,"question":"حكم قول \"لو\" مُحرَّم أم مكروه؟","title":"ما حكم قول \"لو\"؟ ومتى يجوز استعمالها؟","answer":"الجواب: في الحديث النهي عنها، فهي مُحرَّمة؛ لأن الرسول قال: فلا تقل: لو. س: متى يجوز استعمالها؟ ج: يقولها الإنسانُ في استحباب الخيرات، مثل: لو استقبلتُ من أمري ما استدبرتُ ما أهديتُ كما قال النبي ﷺ يوم الحج، حجة الوداع، قال: لو استقبلتُ من أمري ما استدبرتُ ما أهديتُ ولجعلتُها عمرةً، لو علمتُ أنَّ فلانًا هنا لجئتُه وأكرمتُه، وما أشبه ذلك، لو علمتُ أنَّ الطريق آمنٌ حجزتُ. ما في بأس، من باب تمنّي الخير. س: قَدَرُ الله أم قدَّر الله؟ ج: يُقال: قدَّر الله وقَدَر الله، قَدَرُ الله يعني: هذا قَدَر الله، وقدَّر الله: المفعول محذوف، يعني: قدَّر الله هذا الشيء.[1]","link":"https://binbaz.org.sa/fatwas/31244/ما-حكم-قول-لو-ومتى-يجوز-استعمالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alwabel _alsaib 060.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5452,"question":"النجاشي هل هو صحابي أم تابعي؟","title":"هل النجاشي صحابي أم تابعي؟","answer":"الجواب: لا، ما لقي النبي ﷺ. تابعي؛ لأنه ما لقي النبي ﷺ، إنما مكاتبة.[1]","link":"https://binbaz.org.sa/fatwas/31287/هل-النجاشي-صحابي-ام-تابعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 008.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5453,"question":"من أدرك النبي ﷺ ولم يلقه؟","title":"هل يكون صحابيًّا من أدرك النبي ولم يلقه؟","answer":"الجواب: هذا ما يُسمى \"صحابي\"، يُسمى \"تابعي\"، مثل الصنابحي، وكعب الأحبار، هؤلاء يقال لهم تابعيون، وإن كانوا أدركوا النبي ﷺ، لكن ما لقوه، مات ولم يلقوه، قدموا المدينة بعد موته ﷺ.[1]","link":"https://binbaz.org.sa/fatwas/31288/هل-يكون-صحابيا-من-ادرك-النبي-ولم-يلقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/nuzhat_alnthar 009.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5477,"question":"ما الفائدة من أخذ العهد عليهم في ظهر أبيهم آدم؟","title":"ما الحكمة من أخذ العهد من ظهور بني آدم؟","answer":"الجواب: هذا يعني على آدم، لا يُؤاخذ به الإنسان، أُخذ هذا العهد على آدم نفسه، أما الإنسان فيُؤخذ بالرسل التي جاءته. س: قوله تعالى: أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى [الأعراف:172] ما المراد به؟ ج: هذا في الأصلاب، ولا يُؤاخذ به إلا إذا جاءته الرسل.[1]","link":"https://binbaz.org.sa/fatwas/31369/ما-الحكمة-من-اخذ-العهد-من-ظهور-بني-ادم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 002.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5485,"question":"رؤية الله في المنام حسيًّا هل ثبت فيها شيء؟","title":"هل رأى النبي ربَّه في المنام؟","answer":"الجواب: رآه النبيُّ ﷺ في حديث الرؤية، رآه النبيُّ عليه الصلاة والسلام في المنام، وصنَّف في ذلك ابنُ رجبٍ رحمه الله تعالى كتابًا.[1]","link":"https://binbaz.org.sa/fatwas/31383/هل-راى-النبي-ربه-في-المنام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 009.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5490,"question":"الصالحون: ود، وسواع، ويغوث، هل كانوا في زمن نوحٍ أو قبله؟","title":"هل صح أن عبادة الأصنام ستعود مجددًا؟","answer":"الجواب: في زمن نوحٍ. س: لما كانوا أحياء؟ ج: هم موجودون في زمن نوحٍ، ووجودهم قبل نوحٍ، لكن موجودة في زمانه، ثم بقيت في الناس، نسأل الله العافية. س: هناك حديث بأنها ستعود وتُعبد بأعيانها هذه الأصنام؟ ج: لا، في الحديث الصحيح: لا تقوم الساعةُ حتى لا يُقال في الأرض: الله، الله يعني: حتى يعمَّ الشرك -نسأل الله العافية- هي وغيرها إن وُجدت، إن وُجد منها شيء، يعني: تُطبق البلاد على الشرك -نسأل الله العافية- بعدما يُنزع الإيمانُ من قلوب الناس، فإنَّ الله يُرسل ريحًا طيبةً تقبض أرواح المؤمنين، فلا يبقى إلا الكفار، وعليهم تقوم الساعة، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31395/هل-صح-ان-عبادة-الاصنام-ستعود-مجددا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 003.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5492,"question":"هل يجوز أن يُقال لعالم: قد أقامكم الله مفزعًا للمسلمين، وملاذًا للمؤمنين؟","title":"ما حكم قول: \"قد أقامكم الله مفزعًا للمسلمين..\"؟","answer":"الجواب: معناه صحيح: مفزعًا لهم في تحصيل حقوقهم من طريق المحاكم الشرعية، من طريق الإمارة، يفزع لهم الناس لإعطائهم حقوقهم، هذا معناه صحيح، الدعاء لولي الأمر: أن الله يجعله مُوفَّقًا، وأنَّ الله يُعينه على التَّحقيق في حاجات المسلمين، وأن يكون إذا فزعوا إليه حقق طلباتهم من جهة إقامة الحدود، ومن جهة تخليص الحقوق، ومن جهة ردع الظالم، إلى غير ذلك.[1]","link":"https://binbaz.org.sa/fatwas/31396/ما-حكم-قول-قد-اقامكم-الله-مفزعا-للمسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 004.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5511,"question":"إذا صارت مُصيبة للكفار، هل يجوز للمسلم أن يفرح؟","title":"هل للمسلم أن يفرح بالمصيبة في بلد الكفار؟","answer":"الجواب: يفرح لها، إذا كان فيها نفعٌ للمسلمين يفرح لها: قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْيَفْرَحُوا هُوَ خَيْرٌ مِمَّا يَجْمَعُونَ [يونس:58]، إذا كان شيء ينفع المسلمين: انهزم جيشهم، هداهم الله للإسلام؛ يفرح. س: إذا كانت زلزلة مثلًا في بلدٍ كافرٍ؟ ج: يفرح؛ لأنها قد تكون موعظةً، قد تكون فيها هداية.[1]","link":"https://binbaz.org.sa/fatwas/31443/هل-للمسلم-ان-يفرح-بالمصيبة-في-بلد-الكفار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 026.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5550,"question":"وصفه لخطبة رسول الله ﷺ بقوله: خطبةً بليغةً؟","title":"معنى وصف خطبة النبي عليه الصلاة والسلام بأنها بليغةً","answer":"الجواب: يعني عظيمة، بالغ فيها ﷺ، يعني: حمد الله، وأثنى عليه، وذكَّر الناس، وبالغ في تذكيرهم؛ ليحذروا نقمةَ الله. والبليغة هي التي اشتملت على الوعظ والتَّذكير والتَّحذير بألفاظٍ واضحةٍ وبينةٍ، مع الشدة في ذلك وإظهار الخوف عليهم والحذر عليهم. وكان ﷺ إذا خطب اشتدَّ غضبُه، وعلا صوته عليه الصلاة السلام، واحمرَّت عيناه كأنه مُنذر جيشٍ، يقول: صبَّحكم ومسَّاكم، ليست خطبةً ميتةً ضعيفةً، بعض الناس إذا خطب كلامه ضعيف، وكلامه ميت لا يُؤثر في القلوب، بخلاف مَن خطب بقوةٍ وبلاغةٍ، وإيجاد الألفاظ المؤثرة، والصوت المؤثر الذي يشمل اختيار الألفاظ المؤثرة، وإظهار الحزن والخوف على المخاطَبِين.[1]","link":"https://binbaz.org.sa/fatwas/31496/معنى-وصف-خطبة-النبي-عليه-الصلاة-والسلام-بانها-بليغة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 013.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5554,"question":"قوله: إنَّ النبي ﷺ أبو المؤمنين؟","title":"هل يصح أن يُقال: النبي عليه الصلاة والسلام أبو المؤمنين؟","answer":"الجواب: نعم. س: الله يقول: مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ [الأحزاب:40]؟ ج: يعني من جهة نفي التَّبني: ادْعُوهُمْ لِآبَائِهِمْ [الأحزاب:5]؛ لهذا في قراءة بعض القُرّاء قوله جلَّ وعلا: النَّبِيُّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ وَأَزْوَاجُهُ أُمَّهَاتُهُمْ [الأحزاب:6]، قرأ بعضُهم: وهو أبوهم من حيث التربية، أبوة التربية والتَّوجيه، لا أبوة التَّبني، المنفية أبوة التَّبني؛ ولهذا كان يقول لبعض أصحابه: يا بني.[1]","link":"https://binbaz.org.sa/fatwas/31500/هل-يصح-ان-يقال-النبي-عليه-الصلاة-والسلام-ابو-المومنين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 017.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":5639,"question":"المرتد أعرابيًّا بعد الهجرة؟","title":"ما حكم مَن يرتد أعرابيًّا بعد الهجرة؟","answer":"الجواب: ظاهره المنع، لما منّ الله عليه بالهجرة لا يرتد أعرابيًّا إلا لحاجة، إذا ساءت الحال في المدن خرج للبادية لحفظ دينه، كما في الحديث الصحيح أن النبي ﷺ لما سئل عن خير الناس قال: مؤمن مجاهد في سبيل الله، ثم قال: مؤمن في شعب من الشعاب يعبد الله ويدع الناس من شره. س: يكون التعرُّب كبيرة من غير حاجة؟ الشيخ: التعرب بعد الهجرة نعم، من الكبائر، نعم. س: المرتد أعرابيًّا بعد الهجرة هذا الحكم باقٍ إلى الآن؟ الشيخ: نعم إلا لعلة، إذا فسد المجتمع وخرج من المجتمع لحفظ دينه. س: يعني لا يلزم أن يكون هناك هجرة؟ الشيخ: إذا خرج لأجل حفظ دينه؛ لأن المجتمع الحضاري تغير، أبيح له ذلك.[1]","link":"https://binbaz.org.sa/fatwas/31640/ما-حكم-من-يرتد-اعرابيا-بعد-الهجرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 008.mp3","categories":["شروح الحديث","فتاوى متنوعة"]},{"id":7900,"question":"هذه رسالة وافتنا من عبادي الهباش من جدة الجامعة، يقول فيها: محمد سافر إلى الخارج لعدة شهور، وخوفاً من الوقوع في الحرام تزوج بامرأة وفي نيته تطليقها إذا أراد العودة إلى بلده، ما هو الحكم في ذلك، وما هو الحكم إذا لم تكن لديه نية مسبقة بطلاقها وأنجبت له طفل أو طفلة ثم طلقها؟","title":"حكم الزواج بنية جازمة للطلاق","answer":"الجواب: إذا نوى المسافر بزواجه أنه يطلق إذا عزم على الرحيل، هذا فيه اختلاف بين أهل العلم، من أهل العلم من ألحق هذا بالمتعة بنكاح المتعة، ومنهم من قال: لا يلحق بنكاح المتعة وليس منها في شيء؛ لأنه قد ينوي ولا يعزم، ليس بشرط، بخلاف المتعة فإنها مشارطة أنه يطلقها بعد شهر بعد شهرين يفارقها، أما هذا فليس بينه وبينهم مشارطة، إنما في قلبه ونيته أنه إذا أراد الرحيل مثلاً من أمريكا من لندن من كذا من كذا من المغرب من الجزائر طلق، وقد يفسخ هذه النية ويرغب فيها ويرتحل بها.\nفالأقرب والله أعلم أن هذا لا يكون من المتعة، قد يكون جائزاً ولكن الأولى ألا ينوي هذه النية، عليه أن يتزوج ناوياً إن ناسبته ارتحل بها وإلا طلقها.\nأما ينوي نية جازمة أنه يطلقها فالأولى ترك ذلك، خروجاً من خلاف العلماء، هذا هو الأولى، لكن لا يبطل النكاح ولا يكون متعة بهذه النية، هذا هو الصواب، إنما يكون نكاحاً ناقصاً؛ لأن في هذه النية والذي ينبغي أن يكون عليه الرغبة مطلقة، فإذا نوى أنه إذا أراد الرحيل طلق، فالصحيح أنه لا يبطل نكاحه لكنه ترك الذي ينبغي وهو أن ينوي نية مطلقة في الرغبة، إن ناسبته أبقاها وإلا طلقها، هذا هو الذي ينبغي للمؤمن.\nوأما إذا وقع الواقع ونكح مسلمة أو كتابية -يعني- محصنة بعيدة عن الفواحش، فإن الله إنما أباح لنا الكتابيات المحصنات، فإذا نكح كتابية محصنة جاز ذلك، والأولى البعد عن ذلك وترك ذلك؛ لأنها قد تجر عليه بلاء وقد تنجب له أولاداً وتنصرهم؛ فينبغي له الحذر من ذلك، وألا يتزوج إلا مسلمة.\nهذا هو الذي ينبغي حرصاً على سلامة دين أولاده بل على سلامته هو، فقد تجره إلى دينها وتنصره هي، فينبغي له الحذر، وقد يسلم هو ولكن لا تسلم ذريته؛ فينبغي له الحذر وألا يتزوج إلا مسلمة معروفة بالخير من بيئة صالحة؛ لأن هذا هو الذي يرجى فيه الخير، وترجى معه السلامة والإحصان. نعم.","link":"https://binbaz.org.sa/fatwas/5381/حكم-الزواج-بنية-جازمة-للطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_061/06102.mp3","categories":["الطلاق","شروط وأركان الزواج","نكاح الكفار","فتاوى متنوعة"]},{"id":8863,"question":"شيخ عبدالعزيز بين كل فترة وأخرى، وبين كل آونة وآونة تعود إلينا هذه الوصية المزعومة والتي تصدر دائماً تحت اسم الشيخ أحمد حامل مفاتيح حرم رسول الله ﷺ، هذه الوصية تنتشر كما قلت وكلما غابت عادت، يقول في بدايتها هذه المرة: إنه كان في ليلة يقرأ القرآن في حرم رسول الله ﷺ وفي تلك الليلة غلبه النوم ورأى في نومه أن رسول الله ﷺ آت، وقال له: إنه قد مات في هذا الأسبوع أربعون ألفاً من الناس ومن غير الجان، إنهم ماتوا موتة الجاهليين.. ويستمر على هذا الأسلوب.الملاحظ أنه بأسلوب قريب من العامية، أرجو من سماحة الشيخ أن يتفضل بتنبيه الناس على هذه الوصية خاصة وعلى ما ماثلها جزاكم الله خيراً؟","title":"بطلان الوصية المنسوبة للشيخ أحمد حامل مفاتيح الحرم النبوي","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه الوصية قد علمناها من دهر طويل، وهي كما ذكرتم في السؤال كلما ذهبت عادت وكلما نسيت بعثت، ولها مروجون من الناس في سائر أقطار الدنيا باسم خادم الحجرة النبوية، وتارة باسم حامل مفاتيح الحجرة النبوية أو المسجد النبوي، وله فيها عبارات وألفاظ متنوعة، ويقول: إن الرسول صلى الله عليه وسلم أتاه وقال له كذا وكذا، إنه مات أربعون ألفاً ميتة جاهلية، ويقول: إنه يطلع نجم حول الشمس وإنه متى طلع هذا النجم ترونه ولا تقبل الصلوات والعبادات بعد ذلك، ويقول: إن من جاءته هذه الوصية فأهملها وأضاعها يأثم إثماً كبيراً، ومن بلغته ولم ينشرها يخرج من رحمة الله، ويقول: من وزع منها خمساً وعشرين نسخة حصل له كذا وكذا وكذا.. إلى غير هذا من الخرافات، وهذه وصية باطلة لا أساس لها وليس هناك أحمد خادم حجرة النبي ﷺ، كل هذا كذب ، ليس هناك شخص يقال له أحمد وليس هناك وصية، وإنما هذه من كذب الكذابين، أناس يفترون الكذب ويكتبون مثل هذه الوصايا الباطلة وينسبونها إلى من شاءوا من الناس وكل ذلك لا أصل له، وقد سبق أن كتبنا في إبطال هذه الوصية كتابة من أكثر من عشر سنوات ووزعناها في الداخل والخارج بعدة لغات ليفهم المسلمون بطلانها وأنها لا أساس لها، وأن الواجب على من وقعت في يده أن يمزقها وأن يتلفها وينبه الناس على بطلانها.\nالمصحف الذي هو كلام الله  لو أن الإنسان ما كتبه ما عليه شيء ولا بأس عليه، وهذا يقول: من بلغته ولم ينشرها يخرج من رحمة الله!! هذا من أبطل الباطل.\nويقول: من كتب منها خمسة وعشرين نسخة ووزعها يحصل له كذا وكذا .. فوائد، وكذا وكذا وكذا، ومن أعرض عنها يفقد فوائد ويموت ولده وإلا يموت كذا، وإلا يموت كذا، وإلا يصيبه كارثة، كل هذا باطل، القرآن نفسه لو وزع منه مائة نسخة أو كذا وكذا فهو مأجور لكن لا يحصل له هذا الذي قال هذا الكذاب، ولا يكون عليه خطر لو لم يوزع، لو عاش الدهر كله ولم يوزع المصحف لا بأس عليه، للمصحف من يوزعه ومن يبيعه ومن ينشره بين الناس ولو أنه اشتراه من السوق وقرأ فيه ولم يوزعه فلا حرج عليه، ولو كتبه وقرأ فيه ولم يوزعه فلا حرج عليه، كيف بهذه الوصية المكذوبة الباطلة من لم يوزعها يكون عليه كذا وكذا!\nفالمقصود أن هذه الوصية باطلة ومكذوبة ولا أساس لها ولا يجوز اعتقاد هذا الكلام ولا يجوز توزيعها ولا نشرها بين الناس، بل يجب إتلافها والتنبيه على بطلانها، رزق الله الجميع العافية والهدى.\nالمقدم: الواقع سماحة الشيخ مصداقاً لما تفضلتم به أذكر أنني عرضت هذه الرسالة في نفس الفترة التي تفضلتم بتحديدها وهي ما يقرب من عشر سنوات، وقبل فترة أيضاً ناقشناها ونحن هنا في هذا البرنامج نحاربها فضلاً عن توزيعنا لها، وها نحن بحمد الله بصحة جيدة ونذهب ونعود إلى أعمالنا ونحن وأولادنا وأقاربنا وأموالنا بخير وعلى خير.\nالشيخ: الحمد لله، وهذا مثل ما تفضلتم كله واقع، ونحن نحاربها من عشرات السنين ولا رأينا إلا خيراً، كل هذا شيء باطل لا ينبغي التعلق به، نعم، نسأل الله العافية. نعم.\nالمقدم: لعله من المناسب سماحة الشيخ أن تتفضلوا بالتنبيه إلى خطر المطبوعات على العقيدة وعلى الأمن، وعلى أيضاً ما يخص أفكار الناس؟\nالشيخ: ينبغي لمن وجد مطبوعات تلصق بالجدران أو توزع بين الناس أن يسأل عنها أهل العلم وأن لا يعتمد عليها إلا عن بصيرة، إن كان من أهل العلم عرفها بحمد الله ونبه على بطلان الباطل وعلى صحة الصحيح، أما إن كان من العامة فلا ينبغي له أن يتقبل كل ما يوزع بين الناس، بل الواجب أن يسأل أهل العلم في بلاده وفي غير بلاده الذين يثق بهم ويعرف علمهم وفضلهم، يسألهم عما قد يقع في يده، وقد بلغني أن الرسالة التي توزع التي باسمي فيما يتعلق بالأذكار عقب الصلاة، بلغني أن بعض الناس كتب عليها من وزع منها كذا وكذا فله كذا، ومن نشر منها كذا وكذا فله كذا، وهذا كله باطل لا أصل له، ولم أكتب هذا وإنما كتبت بيان الذكر المحفوظ عن النبي عليه الصلاة والسلام بعد الصلوات، أما الزيادة على هذا من فعل كذا أو من نشرها أو من كتب منها كذا وكذا.\nفهذا إن كان وقع فهو باطل لا أساس له ولم أكتبه ولم أمر به، بل هذا من كذب الكذابين، ومن بهتان أهل الباطل نسأل الله العافية.\nوالحاصل أن هذه المسائل التي أشرت إليها وهي الملصقات والموزعات من رسائل وكتب والنشرات يجب الحذر منها، فلا يقبل منها إلا ما كان ثابتاً صحيحاً عن رسول الله عليه الصلاة والسلام مما يبينه أهل العلم العارفون بسنة الرسول عليه الصلاة والسلام، الله المستعان.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7018/بطلان-الوصية-المنسوبة-للشيخ-احمد-حامل-مفاتيح-الحرم-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_138/13801.mp3","categories":["صلاة التطوع","فتاوى متنوعة","مسائل متفرقة في العقيدة"]},{"id":9366,"question":"أخت لنا من السودان بعثت برسالة مطولة وضمنتها اثني عشر سؤالًا متنوعة من أحد أسئلتها: تقول: لي أربعة أطفال، أكبرهم في السابعة من عمره، كانت أمنيتي قبل أن يرزقني الله بهم إن كانت لي ذرية سأحاول بقدر الإمكان تعليمهم أمور الدين وتهيئة الجو الإسلامي لهم، وفعلًا أخذت أعلمهم ومنهم من يحفظ كثيرًا من القرآن الكريم والأحاديث حتى القصص لا يعلمون غير قصص الأنبياء، ولم أدخل عليهم أي جهاز من الأجهزة الحديثة كالمسجل أو الفيديو أو ما أشبه ذلك، إلا أنهم يعيشون في جو غريب تمامًا، وبدءوا يستنكرون كل ما عدا ما في منزلنا أو كل ما عدا ما يسمعون منا، وبدءوا يعيشون في شيء من الازدواجية وترجو التوجيه جزاكم الله خيرًا؟","title":"نصيحة في تربية الأبناء","answer":"الجواب: قد أحسنت في تعليمهم وتوجيههم، وعليك أن تكملي أنت ووالدهم وإخوتهم الكبار وغير ذلك من أقاربهم، عليكم أن تلاحظوهم حتى لا يضرهم ما حولهم من المجتمع، أنت على خير، وأبوهم على خير في التعليم والتوجيه والإرشاد والتربية الإسلامية، ولكن لابد من اختلاطهم بمن حولهم، فعليكم بالحرص عليهم وتوجيههم إلى الخير، وتحذيرهم مما قد يسمعون من الباطل، أو يشاهدون من الباطل حولهم حتى لا يتأثروا به، والله جل وعلا هو الموفق الهادي، وإنما عليكم أن تفعلوا المستطاع: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وأنتم على خير إن شاء الله وسوف ينفع الله بجهودكم. نعم.","link":"https://binbaz.org.sa/fatwas/7530/نصيحة-في-تربية-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18606.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":11676,"question":"رسالة موضوعها في غاية الأهمية -سماحة الشيخ- كتبت بأسلوب عامي بحت صاحبة الرسالة تقول: أختكم في الله التي رمزت إلى اسمها بالحروف (م. ع. س) من المنطقة الجنوبية، سأحاول قراءة الرسالة كما وردت.تقول عن نفسها: إني فتاة أبلغ من العمر السادسة والعشرين، لا أقرأ، ولا أكتب، وطلبت من كان عنده علم كتابة هذه الرسالة: أفيدكم أننا بدو من بوادي أهل الجنوب، وإننا أهل أغنام كثيرة، ولازم نخرج أمام الرجال ونحضر لهم الأكل والشرب ونكلمهم، ولكننا والحمد لله رب العالمين، متقيدين بالإسلام قلوبنا طاهرة، ونحن أمرنا بالحجاب، ونحن متسترون، وقد ذاعت الندوات بالأمر بالحجاب، ولكننا لم نقدر إلا على الغطوة -المراد: غطاء الوجه- ولم نقدر على باقي الحجاب من الجلباب ونحوه، وقد سمعنا أشرطة فيها أحاديث تقول:إن المرأة إذا تغطت، يعني: غطت عيناها، ولم ترتدي الحجاب كاملًا، وتخرج أمام الرجال، وتكلمهم؛ فإنه لا يصح لها أبدًا التحجب؛ لأنها تخرج أمام الرجال وتكلمهم، فنرجو من الله، ثم منكم -جزاكم الله خير الجزاء- أن تفيدونا، هل نمنع الغطوة، أم نخليها؟ لأنها لم توف الحجاب كاملًا بالجلباب؛ لأن هناك أناس كثيرين تركوا الغطوة؛ لأنها ليست من الحجاب الكامل، جزاكم الله خيرًا.","title":"حكم الحجاب وصفته","answer":"الجواب:  الحجاب للمرأة عند غير محارمها أمر لازم؛ لأنها فتنة، والنظر إليها فتنة، فوجب عليها الحجاب ابتعادًا من الفتنة لها ولغيرها، وقد قال الله  في أزواج النبي ﷺ وغيرهن من باب أولى: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]. والحجاب يكون بالجلباب، ويكون بغيره من الملابس التي تغطي البدن، وتستر البدن ومنه الوجه، والوجه هو أعظم الزينة، فستره هو أهم المهمات، هو أعظم الزينة، تستر رأسها، أو وجهها، وسائر بدنها، ولا مانع أن تبدي عينًا، أو عينين للنظر، أو لنظر الطريق، والحاجات التي تريد أخذها وحملها. فالحاصل: أن الحجاب لابد منه في حق المرأة بالنسبة إلى غير محارمها، وقال -جل وعلا-: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ [الأحزاب:59] والجلباب ثوب تلقيه المرأة على رأسها وبدنها زيادة في التحجب والستر، فإذا كانت ملابسها ضافية، وغطت وجهها ورأسها؛ كفى ذلك، لكن الجلباب يكون من مزيد التستر، وهكذا قوله -جل وعلا- في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ [النور:31] الآية، فإذا سترت الزينة وهي الوجه، وبقية البدن بالجلباب أوغيره، حصل المقصود.  ليس المقصود الجلباب وحده، المقصود ما يسترها، ويبعد الخطر والفتنة، فإن تيسر الجلباب وهو الثوب الضافي، تضعه على بدنها، وتستر به وجهها، وبدنها؛ فالحمد لله، وإن ما تيسر فالحجاب بما يسمى الشيلة، أو غير الشيلة مما توضع على الرأس والوجه، ويستر ذلك يكفي ذلك، وإذا سترت الرأس وجعلت على وجهها برقعًا ترى منه حاجاتها، تبدي العين الواحدة، أو عينين، والباقي مستور، لا حرج في ذلك، وإن تيسر الستر للجميع كان ذلك أكمل بالنسبة إلى البعد عن الخطر؛ لأن الناس يختلفون، بعضهم يتأثر بالعين أيضًا، ولكن هديه ﷺ وسنته دل على أن النقاب جائز، ولهذا قال النبي ﷺ في حق المحرمة: ولا تنتقب المرأة، ولا تلبس القفازين فدل على أن غير المحرمة تنتقب، ولا حرج، غير المحرمة تنتقب، أما المحرمة لا تلبس النقاب، والنقاب ما يوضع على الوجه، وفيه نقب للعين والعينين، ويسمى: البرقع، فإذا .... جعلته على وجهها ..... أو نقبت فيه نقبًا، أو نقبين للعينين فقط، مع ستر الوجه كله، الجبهة والخدين؛ فلا بأس بذلك، الله -جل وعلا- يقول: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185]، ويقول سبحانه: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78]. بعض النساء لو جعلت الحجاب ساترًا لعينيها لم تهتدي الطريق، ولم تعرف أن تسير، فلا بد من شيء يعينها على قضاء حاجاتها، وأن يعينها على سيرها في الأسواق وفي بيتها، وحول غنمها، وحول مزرعتها إلى غير ذلك، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، نعم، إذًا ذلك الفهم الذي يقول: إن غطاء الوجه، إما أن يكون كاملًا للبدن كله، أو ليس له أثر فهم خاطئ؟ الشيخ: خاطئ نعم، المهم الستر من جلباب وغيره. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9864/حكم-الحجاب-وصفته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29905.mp3","categories":["حكم الصلاة وأهميتها","اللباس والزينة","فتاوى متنوعة"]},{"id":14434,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (ع. ع. ق) من الدمام، أخونا له عدد من الأسئلة فيسأل في سؤاله الأول ويقول:إذا تزوج الإنسان وهو لا يصلي، لا هو ولا الزوجة، وبعد الزواج بمدة طويلة هداهم الله للصلاة والأمور الشرعية، وفي وقت العقد اكتشف أنه كان محدثًا حدثًا أكبر، ولم يغتسل وقت العقد، بل أجرى العقد وهو على ذلكم الحال، هل العقد صحيح، أم بماذا تنصحونه حيال ما ذكر؟جزاكم الله خيرًا.","title":"حكم العقد إذا كان الزوجان لا يصليان","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإذا كان الرجل والمرأة حين العقد لا يصليان، فالعقد صحيح؛ لأنهما مستويان في ترك الصلاة، وفي الكفر عند من كفرهما بذلك وفي عدمه، فالنكاح صحيح، والصواب أن ترك الصلاة كفر أكبر نعوذ بالله من ذلك، كما قال النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر ولم يقل: بشرط جحدهما الوجوب، بل أطلق -عليه الصلاة والسلام-، فدل على أن من ترك الصلاة كفر، وإن أقر بالوجوب، ومن ذلك قوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، لكنهما مستويان لا يصليان، فالعقد بينهما صحيح كالنصرانيين واليهوديين والوثنيين إذا تزوجا؛ لأنهما مستويان في عدم الدين. أما إذا كان أحدهما يصلي والآخر لا يصلي حين العقد فإن الواجب تجديد العقد بعدما صلى من لا يصلي وتاب إلى الله  يجدد العقد على الصحيح على القول بأن ترك الصلاة كفر أكبر، فيجدد العقد بمهر جديد، وشاهدي عدل، وبواسطة الولي، فالعقد يحضره أربعة: الولي والزوج والشاهدان، فيجدد العقد بمهر وشاهدي عدل بعدما تاب الله على من كان لا يصلي منهما، والحمد لله احتياطًا وخروجًا من خلاف العلماء الذين كفروا تارك الصلاة، وقولهم أصح لظاهر الأدلة الشرعية. وأما كونه تزوج على غير طهارة فهذا لا يضر العقد، وهكذا لو كانت المرأة على حيض حين العقد أو في نفاس لا يضر إذا كانت ليست في عدة، كالبكر عقد عليها وهي في الحيض أو امرأة قد خرجت من العدة عقد عليها وهي في الحيض لا يضر ذلك، ليس من شرط العقد أن يكون الرجل طاهرًا أو المرأة طاهرة، فإذا تم العقد والرجل على جنابة أو المرأة على جنابة أو في حيض أو في نفاس فالعقد صحيح ليس من شرطه الطهارة ما دامت ليست في العدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12909/حكم-العقد-اذا-كان-الزوجان-لا-يصليان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62401.mp3","categories":["الطلاق","شروط وأركان الزواج","نكاح الكفار","فتاوى متنوعة"]},{"id":14564,"question":"سماحة الشيخ، بعض الآباء في المعاملة يميلون إلى البعض دون الآخرين، ويفرقون بينهم، هل من توجيه للآباء حول ذلك؟","title":"توجيه للأباء الذين لا يعدلون بين أولادهم","answer":"الجواب: الواجب على الآباء والأمهات تقوى الله في أولادهم، والعدل بينهم في النصيحة والتوجيه والإرشاد والتعليم؛ لأنهم جميعًا في الذمة أمانة، فيجب على الوالدين أن يتقوا الله في أولادهم، وأن يجتهدوا في تربيتهم التربية الإسلامية، وأن يحرصوا على الجد في الإحسان إليهم جميعًا، وعدم التخصيص؛ لأنهم جميعًا في الذمة.  فالواجب العناية بهم جميعًا، والحرص على تربيتهم التربية الإسلامية، وإذا كانوا محاويج جميعًا وجب الإنفاق عليهم بحسب حاجتهم إذا كان والدهم قادرًا على ذلك. أما أن يخص بعضهم من غير موجب شرعي، بل بالهوى فلا يجوز، فالواجب تقوى الله والعدل، كما قال النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم. فعلى الأب وعلى الأم العدل، وتحري الحق في تربية الأولاد، والإنفاق على الأولاد وغير ذلك، لكن من عصى الله من الأولاد وعق والديه لا يكون له حق مثل حق من أطاع وبر بوالديه، من عصى والديه وعقهم فهو يستحق العقوبة والتأديب، وليس له حق مثل حق من أطاع وبر، فالعاق يؤدب ويعامل بما يستحق حتى يدع العقوق، وحتى يستقيم على بر والديه، ولا يكون له من الحق مثل حق من بر والديه، واستقام على طاعة الله فيهما. وهكذا من كان غنيًا ليس له حق فيما يعطاه الفقير، إذا كان أحد الأولاد فقيرًا أو مريضًا ليس عنده قدرة على الكسب، وأبوه يستطيع فإنه ينفق عليه، وليس للغني حق في ذلك، بل هذا من أجل الحاجة، فالأب ينفق على ولده الفقير والأم كذلك، ولا يكون جائرًا ولا ظالمًا إذا أنفق على الفقير، وعالج المريض؛ لأنه لا يستطيع، وترك القادر الذي يستطيع عنده المال ينفق على نفسه، ويعالج نفسه فهو مستغن عن والديه بما أعطاه الله من المال. أما الفقير كالطفل والمريض الذي ليس عنده ما يعالج به ونحو ذلك ممن يعجز عن النفقة لفقره أو مرضه أو علة به أو نحو ذلك ليس مثل الصحيح الغني، والله -جل وعلا- يقول سبحانه في كتابه العظيم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول -جل وعلا-: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فعلى المؤمن أن يتقي الله في جميع ما يأتي ويذر حسب شرع الله، وعليه أن يحذر الظلم والعدوان في أولاده أو في غيرهم، بل عليه أن يتحرى الحق أو العدل في كل شيء، وفق الله الجميع، نعم. المقدم: اللهم آمين، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13061/توجيه-للاباء-الذين-لا-يعدلون-بين-اولادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55602.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":15263,"question":"سماحة الشيخ، تساهل الكثير من الناس في الانصراف عن أطفالهم، يبلغون الحادية عشرة، والثانية عشرة وهم مهملون لهم، هل من توجيه للآباء والأمهات؟","title":"توجيه لمن يهملون أولادهم ولا يحثونهم على الصلاة","answer":"الجواب: نعم، لا يجوز هذا، الواجب على الآباء والأمهات توجيه الأولاد ونصيحتهم، إذا بلغ سبعًا أن يؤمر بالصلاة، والمرأة والبنت تؤمر بالصلاة وتعلم، والولد كذلك يؤمر ويعلم، ويخرج به أبوه أو أخوه إلى المسجد، وإذا بلغ عشرًا يضرب؛ لقوله ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع هذا هو الواجب، متى بلغ عشرًا فأكثر يؤمر بالصلاة مع الناس، ويضرب إذا تخلف، يضربه أبوه أو أخوه الكبير أو عمه، أما إذا بلغ الحلم، فإنها تجب عليه تكون فريضة، إذا تركها كفر، نسأل الله العافية.  أما ابن سبع وابن ثمان وابن تسع هذا يؤمر ولا يضرب، نعم، الله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13756/توجيه-لمن-يهملون-اولادهم-ولا-يحثونهم-على-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56511.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":15354,"question":"المستمع حسين علي محمد، بعث يسأل عن تفسير بعض الآيات القرآنية، منها: قوله تعالى أعوذ بالله من الشيطان الرجيم : أَأَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الأَرْضَ فَإِذَا هِيَ تَمُورُ [الملك:16] وقوله تعالى: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [يونس:3] يرجو أن تفسروا هذه الآيات، وعنون لها بقوله: آيات عن العلو والاستواء.","title":"تفسير بعض الآيات الدالة على علو الله","answer":"الجواب: هذه الآيات الكريمات فسرها أهل العلم من أهل السنة والجماعة كـالبغوي في التفسير، وابن كثير، وابن جرير، وغيرهم، ومعناها عند أهل السنة واضح، فقوله -جل وعلا-: أَأَمِنتُمْ مَنْ فِي السَّمَاءِ: يفسر بمعنيين:  أحدهما: في السماء يعني: المبنية السماوات المعروفة، فيكون معنى في يعني: على، من على السماوات، كما قال -جل وعلا-: فَسِيرُوا فِي الأَرْضِ [آل عمران:137] يعني: على الأرض، قال -جل وعلا- عن فرعون أنه قال لخصومه: وَلَأُصَلِّبَنَّكُمْ فِي جُذُوعِ النَّخْلِ [طه:71] يعني: على جذوع النخل. والمعنى الثاني: أن المراد بالسماء العلو، جهة العلو، فتكون (في) للظرفية، والمعنى (أأمنتم من في العلو) وهو الله سبحانه، فإنه في العلو فوق العرش -جل وعلا-، قد استوى على العرش استواء يليق بجلاله وعظمته، لا يشابه الخلق في شيء من صفاته ، فهو فوق جميع الخلق، في أعلى شيء، فوق جميع الخلق . وهكذا قصد فرعون اللعين حين قال: يَا هَامَانُ ابْنِ لِي صَرْحًا لَعَلِّي أَبْلُغُ الأَسْبَابَ [غافر:36] يعني: الطرق، أَسْبَابَ السَّمَاوَاتِ[غافر:37] يعني: طرق السموات، فَأَطَّلِعَ إِلَى إِلَهِ مُوسَى [غافر:37] عرف الخبيث أنه في العلو؛ لأن موسى بلغه أنه في العلو؛ ولهذا زعم هذا الزعم، وهو لا يستطيع ذلك، ولا هامان، فإن العلو إلى السماوات لا يستطيعه المخلوق إلا بأمر من الله ، كما عرج الله بنبينا محمد ﷺ إلى العلو، مع جبرائيل -عليه الصلاة والسلام-. فالسماوات لها أبواب، ولها حرس، لا يستطيع أحد الدخول إليها إلا بإذن من الله ، وهذه من مكابرة فرعون من مكابرته ودعاواه الباطلة، وهو يعلم أن الله في العلو، كما أخبره موسى، فلهذا قال هذه المقالة، وهي من أدلة أهل السنة على أن الله في العلو، وأن موسى بلغ فرعون أن الله في العلو، فلهذا قال هذه المقالة. وهكذا قوله سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] يعني: ثم علا على العرش، وهذا قاله سبحانه في سبعة مواضع في كتابه -جل وعلا-، بين في ذلك استواءه على العرش  وأنه فوق العرش، كما قال في سورة طه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] فالمعنى الاستواء: العلو والارتفاع، ومنه استوى على السفينة يعني: ارتفع عليها، ومنه اسْتَوَتْ عَلَى الْجُودِيِّ [هود:44] يعني: ارتفعت على الجودي. فالاستواء معناه: العلو والارتفاع، استوى فلان على الدابة يعني: صار على ظهرها، واستوى على السطح: صار فوق السطح، واستوى على الجمل: صار فوق الجمل، فمعنى استوى على العرش يعني: ارتفع فوق العرش -جل وعلا-، واستواؤه يناسبه سبحانه، ويليق به ، ولا يشابه الخلق في استوائهم على دوابهم، وعلى الجبال، وعلى غير هذا. وهكذا كل صفات الله تليق به ، ولا يشبه فيها خلقه -جل وعلا- كما قال سبحانه: لََيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقال : وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] وقال سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ[النحل:74] وقال : هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65] يعني: لا سمي له، ولا كفء له ، وهكذا أمثال هذه الآيات كلها تدل على علو الله، وأنه فوق العرش، مثل وَهُوَ الْعَلِيُّ الْعَظِيمُ [الشورى:4] .. فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12] هو العلي العلو الكامل، علو الذات، وعلو القهر والسلطان، وعلو المكان، فهو فوق العرش -جل وعلا-، فوق جميع الخلق . والعرش سقف المخلوقات وأعلاها، والله فوقه ، ومع هذا لا يخفى عليه شيء من أحوال عباده، يعلم كل شيء ، نعم، الله أكبر! نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13857/تفسير-بعض-الايات-الدالة-على-علو-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_498/49804.mp3","categories":["الأسماء والصفات","فتاوى متنوعة"]},{"id":15628,"question":"يقول السائل: في هذه الأيام يفضل التمييز بين الأبناء، يقول: وهذا يخلق عداوة بين الإخوان فيما بينهم أفيدونا بتوجيه الآباء ونصيحتكم. جزاكم الله خيرًا.","title":"ما النصيحة للآباء في المفاضلة بين الأبناء؟","answer":"الجواب: لا يجوز للآباء تفضيل بعض الأولاد على بعض، لا يجوز لهم ذلك، بل هذا منكر؛ النبي ﷺ لما سأله بشير بن سعد أن يعطي النعمان ولده غلامًا قال: أعطيت ولدك كلهم؟ قال: لا، قال: اتقوا الله واعدلوا بين أولادكم وأراد أن النبي ﷺ يشهد فقال: إني لا أشهد على جور سماه النبي ﷺ جورًا. فالمقصود: أنه لا يجوز للأم ولا للأب التفضيل بين الأولاد، بل يجب التسوية بينهم للذكر مثل حظ الأنثيين، فلا يجوز أن يعطى زيد كذا، ويترك الآخر، لا، بل يجب التعديل بين الأولاد ذكورهم وإناثهم؛ ولهذا في الحديث الآخر: أيسرك أن يكونوا لك في البر سواء؟ قال: نعم، قال: فهكذا؛ لأنه إذا فرق بينهم ساءت أحوالهم، وربما قطعوه أيضًا. فالواجب على الأب والأم والجد والجدة عدم التفضيل، بل يجب العدل للذكر مثل حظ الأنثيين، إذا أعطى الذكر مائة يعطي الأنثى خمسين، وإذا أعطى الرجل ألفًا يعطي الأنثى خمسمائة وهكذا، يجب التعديل؛ لقوله ﷺ: اتقوا الله واعدلوا بين أولادكم ولقوله لـبشير بن سعد الأنصاري لما أراد أن يشهده على عطيته للنعمان وحده قال: إني لا أشهد على جور وقال لـبشير: أيسرك أن يكونوا لك في البر سواء؟ قال: نعم، قال: فلا إذًا يعني: فلا تخص بعضهم، سوِّ بينهم حتى يكونوا كلهم في البر لك سواء، نعم. المقدم: أحسن الله إليكم وبارك فيكم..","link":"https://binbaz.org.sa/fatwas/14169/ما-النصيحة-للاباء-في-المفاضلة-بين-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57111.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":15806,"question":"قضية طويلة بعض الشيء يقول صاحبها: رجل من أهل البادية في يوم من الأيام ذهب في دورة بعض المواشي، فابتعد عن أماكن الماء والأكل والناس، واشتد عليه العطش نتيجة لشدة البحث عن المواشي في صحراء جرداء، وقيض شديد، وحاول البحث عن ماء فلم يجد شيئًا مما اضطره إلى تسليم أمره لله، واستعد للموت، فسقط على الأرض مغشيًا عليه، وبينما هو على هذه الحال في وسط الصحراء تلفحه حرارة الشمس الشديدة، ومتجردًا من ملابسه، ومغمًا عليه، لا يحس بمن حوله، بينما هو كذلك؛ إذ قدم رجل بفضل الله، فأنقذه من هذه الحالة، وأعطاه الماء والملابس، وأطعمه، وأخذه معه حتى وعى من غيبوبته تلك. و إنه نتيجة لهذه المعاملة الحسنة التي لقيها من هذا الرجل الذي مر عليه، فإنه قد تأثر نفسيًا تأثيرًا بالغًا حتى قال: إنك أخ لأولادي ولزوجتي، وأنت كالمحرم لهن، هل ما فعل صحيح؟جزاكم الله خيرًا.","title":"حكم جعل الرجل غيره محرمًا لأهله","answer":"الجواب: هذا الذي أنقذه قد فعل معروفًا، قد أحسن، وله أجره عند الله  حيث أنقذ نفسًا أشرفت على الهلاك، فهو مأجور بهذا العمل، وله ثواب جزيل، لكن لا يكون بذلك محرمًا لزوجة المنقذ ولا لبناته، ولكنه أخوهن في الله، وقد أحسن إلى أب البنات وإلى زوج المرأة إحسانًا كبيرًا، ولكنه لا يكون بهذا محرمًا، ولا يكون أخًا للمنقذ ولا أبًا له، ولا ابنًا له، وإنما هو أخوهم في الله إذا كانا مسلمين جميعًا، فكلهم إخوة في الله، ولكن المحرمية لا تثبت بهذا، فكونه أنقذ إنسانًا لا يكون بذلك محرمًا لبناته أو زوجته أو غيرهن، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14394/حكم-جعل-الرجل-غيره-محرما-لاهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74309.mp3","categories":["الآداب والأخلاق المحمودة","فتاوى متنوعة"]},{"id":15961,"question":"أختنا السائلة أم عبدالله تقول في هذا  لدي أخوات وعمات وخالات متفرقات: واحدة في الشمال، والأخرى في الجنوب، وأخرى في الغرب، وفيهم كبار السن، والصغار، والبعض منهم يملك هاتف، والبعض الآخر لا يملك هاتف، ولا أستطيع أن أقوم بزيارتهم؛ لأن الزيارة مكلفة، فالواحد منهم إذا أراد أن يزور هذا القريب يجب أن يعطيه مبلغ من المال، وفوق هذا تكاليف السفر باهظة جدًا. السؤال يبقى -يا سماحة الشيخ-: هل المكالمات الهاتفية تكفي عن صلة الرحم، أم يجب الذهاب إليهم في ذلك؟ مأجورين.","title":"وسائل صلة الأرحام","answer":"الجواب: الصلة من جهة مواصلتهم بالمكاتبة أو بالهاتف طيبة، ويحسن بها وصل الرحم، بالهاتف بالتلفون، بالمكاتبة بالسلام الذي يحمله فلان: سلم لنا على فلان، على أخي فلان، على عمي، على خالي، كل هذا من صلة الرحم، وإذا تيسرت الزيارة بلا تكلفة فهي من كمال الصلة: الزيارة، وبذل المال إذا كانوا محاويج، أو يسرهم بذل المال؛ هذا من الصلة، الهدية الطيبة، مواساة الفقير؛ هذا من الصلة الواجبة -صلة الرحم­-، وإذا كانوا أغنياء فالكلام الطيب والمكاتبة الطيبة والمكالمة الهاتفية، ولو ما تسافر إليهم يكفي بالمكالمة الهاتفية والمكاتبة تكفي، وإذا كانوا فقراء أو يمكن يعني: يحتاجون إلى هدية يهدي إليهم، والفقير يواسى إذا كان يستطيع يواسيهم من الزكاة أو من غيرها، كل هذا من صلة الرحم، نسأل الله للجميع الهداية والتوفيق، نعم. المقدم: اللهم آمين، أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14567/وساىل-صلة-الارحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57813.mp3","categories":["الآداب والأخلاق المحمودة","فتاوى متنوعة"]},{"id":16361,"question":"هذا السائل يقول في هذا السؤال سماحة الشيخ: ذهبنا لتوصيل أحد الإخوان إلى مطار الملك خالد في الرياض، فأخبرنا أحد الإخوة بأنه يجوز لنا القصر مع أننا لسنا بمسافرين، فصلينا العشاء قصرًا، وصلى معنا المسافر أيضًا قصرًا، فهل عملنا صحيح؟ وهل علينا الإعادة؟ علمًا بأن المطار يبعد عن منزلنا حوالي ستين كيلو مترًا.","title":"حكم القصر والجمع لمن ذهب إلى المطارات البعيدة","answer":"الجواب: الذهاب إلى المطار مطار الرياض، أو مطار جدة، أو ما أشبهها ما يسمى سفرًا، هذا من باب التنقل في البلد، وأطراف البلد، لا يسمى سفرًا، المسافر الذي بيرتحل له يقصر في المطار قبل أن يركب الطائرة، أما الذي يشيعه مشيعون سيرجعون إلى البلد هؤلاء ليسوا مسافرين، في مطار جدة، أو مطار الرياض، أو ما أشبهها، هذه الأشياء تبع البلد، ما يسمى صاحبها مسافرًا، من ذهب إليها لا يسمى مسافرًا، وليس له القصر، ولا الجمع، نعم. المقدم: أيضًا الموظفون يا شيخ الذين يعملون هناك.. الشيخ: والموظفون كذلك ليسوا مسافرين، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15060/حكم-القصر-والجمع-لمن-ذهب-الى-المطارات-البعيدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58111.mp3","categories":["صلاة المسافر","فتاوى متنوعة"]},{"id":16400,"question":"لها سؤال مطول بعض الشيء تقول فيه: هل قراءة القرآن عند القبور بدعة، وخاصة سورة الفاتحة، وسورة البقرة، علمًا بأني قرأت في كتاب الروح لابن القيم عن قراءة القرآن عند دفن الميت، وقراءة القرآن أيضًا عقيب الدفن، ومثال ذكر على ذلك: أن جماعة من السلف أوصوا بأن يقرأ عند قبورهم وقت الدفن، قال عبدالحق: يروى أن عبدالله بن عمر أمر أن يقرأ عند قبره سورة البقرة، وممن رأى ذلك المعلا بن عبدالرحمن، وكان الإمام أحمد ينكر ذلك أولًا: حيث لم يبلغه فيه أثر، ثم رجع عن ذلك، أفيدونا عن هذا الأمر؟ جزاكم الله خيرًا.","title":"هل قراءة القرآن عند القبور بدعة؟","answer":"الجواب: القراءة عند القبور بدعة، ولا يجوز فعلها، ولا الصلاة عندها؛ لأن الرسول ﷺ لم يفعل ذلك، ولا أرشد إليه، ولا خلفاؤه الراشدون؛ ولأن هذا مما يفعل في المساجد، والبيوت، يقول ﷺ: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا فدل على أن القبور ما يصلى عندها، ولا يقرأ عندها، إذ هذا من خصائص المساجد والبيوت، إنما يسلم على أهلها، يزارون، ويسلم عليهم، ويدعى لهم، وكان النبي ﷺ: (إذا فرغ من دفن الميت؛ وقف عليه، وقال: استغفروا لأخيكم، وسلوا له التثبيت؛ فإنه الآن يسأل ولم يقرأ عنده، ولم يأمر بالقراءة عنده. وما يروى عن عبدالله بن عمر إن صح عنه لا يعول عليه؛ لأن العبادات تتلقى من الرسول ﷺ أو من القرآن، ولا يحتج فيها بقول صاحب، ولا غيره، ما عدا الخلفاء الراشدين حيث قال فيهم النبي ﷺ: عليكم بسنتي، وسنة الخلفاء الراشدين من بعدي، تمسكوا بها، وعضوا عليها بالنواجذ فما جاء عن الخلفاء الراشدين المهديين يعتمد إذا كان لا يخالف سنته -عليه الصلاة والسلام- وأما ما يروى عن ابن عمر، أو غيره من الصحابة، وغيرهم في العبادات؛ فلا يعول عليه؛ لأن العبادة توقيفية، العبادات توقيفية، لا تؤخذ إلا عن القرآن، أو السنة الصحيحة عن رسول الله، عليه الصلاة والسلام. وما ذكره ابن القيم عن بعض العلماء لا يعتمد عليه، الواجب في مثل هذا الباب هو الاعتماد على القرآن والسنة، وما خالفهما من جهة العبادة يكون بدعة، فلا يصلى عند القبور، ولا يقرأ عندها، ولا يطاف بها، ولا تدعى من دون الله، ولا يستغاث بأهلها. فدعاء الميت، والاستغاثة بالميت، والنذر له هذا من الشرك الأكبر، والدعاء عند قبر كونه يدعو الله عند قبر بدعة، وهكذا القراءة عند القبر بدعة، نعم. المقدم: جزاكم الله خيرًا، هل رجع الإمام أحمد فعلًا عن القول بهذا؟ جزاكم الله خيرًا. الشيخ: يروى هذا، ولا أعرف عن صحته، ولو رجع عنها، ولو قاله أحمد، وأحمد يخطي ويصيب مثل غيره من العلماء، ابن عمر أفضل من أحمد، فالعمدة على الكتاب والسنة، يقول الله -جل وعلا- في كتابه العظيم: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59] ويقول -جل وعلا-: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]، ويقول جل وعلا: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]. فهذه العبادات هذه المسائل العظيمة يتلقاها المسلمون عن القرآن العظيم والسنة المطهرة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15104/هل-قراءة-القران-عند-القبور-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81108.mp3","categories":["البدع والمحدثات","فتاوى متنوعة"]},{"id":16702,"question":"تقول يا سماحة الشيخ هذه السائلة من الإمارات: سمعت أن آية في كتاب الله  وهي في قوله تعالى: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ [الزمر:53] تقول: سمعت بأن هذه هي أرجى آية في القرآن العظيم، فما معنى ذلك؟","title":"ما أرجى آية في القرآن؟","answer":"الجواب: لأن الله سبحانه هو وعد بالمغفرة، وعد المسلمين بالمغفرة، فهي بهذا المعنى أرجى آية، ولو ماتوا على ذنوب عظيمة إذا تابوا منها، هذه الآية أجمع العلماء -رحمة الله عليهم- على أنها في التائبين، وهي قوله سبحانه: قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا [الزمر:53] يعني: للتائبين، في الشرك، وما دونه، من تاب إلى الله؛ تاب عليه توبة صادقة، إذا ندم على ما مضى منه، وأقلع منه، وعزم ألا يعود فيه؛ تاب الله عليه، سواءٌ كان شركًا، أو زنا، أو خمرًا، أو غير ذلك، المهم أن يندم ندمًا صادقًا عليه، وأن يقلع منه، ويتركه؛ خوفًا من الله، وتعظيمًا له، وإخلاصًا له، ويعزم عزمًا صادقًا ألا يعود فيه، هذه شروط ثلاثة:  الشرط الأول: الندم على الماضي. الشرط الثاني: الإقلاع منه، وتركه، والحذر منه؛ تعظيمًا لله، وطاعة لله. والشرط الثالث: العزم الصادق ألا يعود فيه. فإذا توفرت هذه الشروط الثلاثة؛ فإن الذنوب تغفر بإجماع المسلمين؛ لهذه الآية الكريمة؛ ولعموم قوله -جل وعلا-: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] ولقوله سبحانه: وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنْفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَنْ يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ ۝ أُوْلَئِكَ جَزَاؤُهُمْ مَغْفِرَةٌ مِنْ رَبِّهِمْ وَجَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ [آل عمران:135-136]. فمن تاب من الذنب، ولم يصر عليه؛ تاب الله عليه، سواء كان الذنب شركًا، أو معصية، هذا بإجماع المسلمين، لكن إذا كان الذنب حقًا لإنسان يعني ظلم، فلابد يعطيه حقه، من تمام التوبة أن يعطيه حقه. الشرط الرابع: إذا كان الذنب يتعلق بالمخلوق، ضربه، أو أخذ ماله، أو قتله؛ لابد يعطيه حقه، القصاص في القتل، وإعطاء حق المال، وهكذا إذا ظلمه بشيء آخر يستحله، هذا شرط رابع، لابد من إعطاء صاحب الحق حقه إذا كان الحق للمخلوق. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15436/ما-ارجى-اية-في-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58418.mp3","categories":["الرقائق","فتاوى متنوعة"]},{"id":17026,"question":"يقول: نعلم جيدًا أن من السنة قول: آمين بعد قراءة الفاتحة بالصلاة، بحيث يجهر بها في الصلاة الجهرية، ونسر بها في الصلاة السرية، ولكن عندنا في المسجد يقولون: آمين في الصلاة الجهرية بعد قراءة الفاتحة في السر، ولا يرفعون بها أصواتهم، ويقولون: إن ذلك مذهب الإمام مالك، ما هو توجيهكم؟","title":"صفة التأمين بعد قراءة الفاتحة","answer":"الجواب: الصواب رفع الصوت بها كما كان النبي يفعل ﷺ والصحابة يفعلون، فإذا قال: وَلا الضَّالِّينَ [الفاتحة:7]؛ يقول الإمام: آمين وهم كذلك، يقول النبي ﷺ: إذا قال الإمام: ولا الضالين فقولوا: آمين، فمن وافق قوله قول الملائكة؛ غفر له ما تقدم من ذنبه فالسنة رفع الصوت بها من الجميع، الإمام والمأموم جميعًا، والمنفرد في الجهرية، هذا هو السنة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15815/صفة-التامين-بعد-قراءة-الفاتحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83007.mp3","categories":["مسائل متفرقة في العقيدة","فتاوى متنوعة"]},{"id":17180,"question":"يسأل عن كيفية التسبيح بعد كل صلاة؟ جزاكم الله خيرًا.","title":"كيفية التسبيح والذكر بعد كل فريضة","answer":"الجواب: السنة بعد الصلاة الفريضة أن يقول أستغفر الله، أستغفر الله، أستغفر الله ثلاث مرات، بعد الظهر، والعصر، والمغرب، والعشاء، والفجر، اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام أول ما يسلم الإمام، والمنفرد، والمأموم، كل واحد إذا سلم يقول: أستغفر الله.. أستغفر الله ..أستغفر الله، اللهم أنت السلام ومنك السلام تباركت يا ذا الجلال والإكرام قبل كل شيء، هذا أول شيء، ثم الإمام ينصرف إلى الناس، بعد هذا ينصرف الإمام إلى الناس، ويعطيهم وجهه.  ثم يقول بعد ذلك الإمام، والمنفرد والمأموم: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير مرة واحدة، أو ثلاث مرات، كله جاءت به السنة، ثم يقول بعدها: لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين، ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد يعني: ذا الغنى منك غناه. هذه السنة للجميع، الإمام، والمنفرد، والمأموم، بعد قوله: أستغفر الله ثلاثًا، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام يأتي بهذا الذكر. أعيده لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير وإن شاء زاد: يحيي ويميت بيده الخير، وهو على كل شيء قدير أو يحيي، ويميت، وهو حي لا يموت، بيده الخير، وهو على كل شيء قدير كله جاء في الأحاديث لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير وإن شاء قال: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت، وهو على كل شيء قدير وإن شاء قال: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، يحيي ويميت بيده الخير وهو على كل شيء قدير وإن شاء قال: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، يحيي ويميت، وهو حي لا يموت، بيده الخير، وهو على كل شيء قدير كل هذا جاءت به النصوص.  ويقول بعدها: لا حول ولا قوة إلا بالله ثم يقول: لا إله إلا الله، ولا نعبد إلا إياه، له النعمة، وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين يعني: له العبادة، الدين معنى العبادة، مخلصين له الدين، ولوكره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد كل هذا فعله النبي ﷺ بعد كل صلاة، عليه الصلاة والسلام. فالسنة للإمام، والمنفرد، والمأموم يقول هذا، تأسيًا بالنبي -عليه الصلاة والسلام- بعد الظهر والعصر، والمغرب، والعشاء، والفجر. ويستحب أن يزيد في المغرب، والفجر زيادة عشر مرات لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، يحيي ويميت وهو على كل شيء قدير عشر مرات، مع ما ذكر في الفجر، والمغرب خاص؛ لأنه جاء عن النبي ﷺ أنه كان يفعل ذلك، عشر مرات يقول: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، يحيي ويميت، وهو على كل شيء قدير عشر مرات، يقولها بعد المغرب زيادة، وبعد الفجر. ويستحب بعد هذا كله أن يقول: سبحان الله، والحمد لله والله أكبر ثلاثة وثلاثين مرة، سبحان الله، والحمد لله، والله أكبر جميع ثلاثة وثلاثين مرة، هذه تسعة وتسعون، ثم يقول بعد ذلك تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير ثبت عن النبي ﷺ أنه قال: من فعل هذا؛ غفر له خطاياه، وإن كانت مثل زبد البحر هذا فضل عظيم. فيستحب للمؤمن، والمؤمنة جميعًا أن يأتيا بهذا الذكر الذي تقدم كله، الرجل والمرأة جميعًا، ويستحب للجميع أيضًا أن يقول كل واحد: سبحان الله، والحمد لله، والله أكبر ثلاثًا وثلاثين مرة، ويقول مع ذلك في آخر ذلك: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير.  جاء في الحديث الصحيح \"أن العبد إذا قال هذا؛ غفرت خطاياه وإن كانت مثل زبد البحر\" هذا وعد عظيم، وفضل كبير، والمعنى: إذا لم يصر على السيئات، هذه المغفرة جاءت الأحاديث الأخرى تدل على أنها مقيدة بعدم الإصرار على الكبائر.. على المعاصي، لقول الله سبحانه في كتابه العظيم: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31].   فالمسلم إذا تجنب الكبائر، كالزنا، والسرقة، والعقوق للوالدين، أو أحدهما، وشرب الخمر، والغيبة، والنميمة، وأشباهها من الكبائر.. إذا تجنبها؛ غفر الله له خطاياه في صلاته، ووضوئه، وتسبيحاته، وغير ذلك من وجوه الخير، وهذا معنى قوله سبحانه: إِنْ تَجْتَنِبُوا كَبَائِرَ مَا تُنْهَوْنَ عَنْهُ نُكَفِّرْ عَنْكُمْ سَيِّئَاتِكُمْ وَنُدْخِلْكُمْ مُدْخَلًا كَرِيمًا [النساء:31]. ويقول النبي ﷺ: الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، مكفرات لما بينهن إذا اجتنب الكبائر . ويستحب أيضًا للمؤمن، والمؤمنة بعد كل صلاة مع ما تقدم أن يقرأ آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ لَهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255]  هذه آية الكرسي، ينبغي حفظها الرجل، والمرأة، كل واحد ينبغي عليه حفظها: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ يعني: النعاس وَلا نَوْمٌ لَهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] يقرؤها المؤمن والمؤمنة بعد كل صلاة، مؤمنًا بما دلت عليه، ومؤمنًا بما فيها. ويستحب أيضًا أن يقرأ: قل هو الله أحد والمعوذتين بعد كل صلاة قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] بسم الله الرحمن الرحيم قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِنْ شَرِّ مَا خَلَقَ ۝ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ [الفلق:5] بسم الله الرحمن الرحيم قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ [الناس:6]. بعد كل صلاة، كل هذا مستحب، لكن يكررها بعد المغرب، والفجر ثلاث مرات، بعد المغرب خاصة، والفجر ثلاث مرات، يكرر قل هو الله أحد وقل أعوذ برب الفلق وقل أعوذ برب الناس مع التسمية في كل واحدة، ويستحب أن يقرأها عند النوم أيضًا، آية الكرسي، وهذه الثلاث السور عند النوم، يقرأ آية الكرسي مرة واحدة، ويقرأ هذه السور عند النوم ثلاث مرات، عند النوم، هذه من أسباب السلامة، والعافية من كل سوء، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15999/كيفية-التسبيح-والذكر-بعد-كل-فريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_832/nour_83204.mp3","categories":["مسائل متفرقة في العقيدة","فتاوى متنوعة"]},{"id":17335,"question":"هذا السائل عز الدين (م. ص) يقول: رجل يصلي معنا وفي الصف الأول، وهو جار للمسجد، ولكنه يقف ضد توسعة المسجد، ويدعي بأن ذلك ضرر عليه، وليس هنالك أي ضررٍ عليه، ولكن لا ندري لماذا، و كيف نتعامل مع هذا الرجل؟ وكيف نتصرف معه؟ مع أنه يفعل هذا الشيء منذ أكثر من ثلاث سنوات، وهو رجل قد بلغ الستين، أفتونا يا سماحة الشيخ؟","title":"حكم الوقوف ضد توسعة المسجد","answer":"الجواب: السؤال فيه إشكال، ما هو بواضح، لكن إن كان المقصود من هذا أنه يعارض في توسعة المسجد، والمسجد صغير، ويراد توسعته، وهو يعارض؛ فلا ينظر فيه، ينظر الإمام والجماعة، فإذا تيسر توسيعه من أحد الجانبين، أو أحد الجوانب وسعوه، ولا يلتفت إلى قوله. أما إن كان المقصود أنه ما يصلي في التوسعة، المسجد وسع، ولا يصلي في التوسعة؛ هذا غلط منه، عليه أن يصلي في الصف الأول، ولو كان في التوسعة، التوسعة إنما جاءت لتوسيع المسجد، فإذا كان المراد يعني إنه يتورع عن الصلاة في التوسعة، ويصلي في المسجد القديم هذا غلط، بل إذا صاف الناس في التوسعة؛ صف معهم، سواء كانت التوسعة في جنوب المسجد، أو شماله، أو غربه، أو شرقه، المقصود التوسعة يصلى فيها، فالسؤال فيه إشكال ما هو بواضح. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16165/حكم-الوقوف-ضد-توسعة-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59317.mp3","categories":["مسائل متفرقة في العقيدة","فتاوى متنوعة"]},{"id":17340,"question":"هذا سائل للبرنامج يقول: يا سماحة الشيخ، السائلة أختكم في الله مستمعة دائمة للبرنامج، رمزت لاسمها بهذا الرمز، تقول سماحة الشيخ: هل يحاسب الإنسان عن أخطائه، وذنوبه التي ارتكبها قبل بلوغه، فأنا يا سماحة الشيخ في صغري كنت قد ارتكبت من الأخطاء، والذنوب الكثير حتى منَّ الله  علي بالهداية، ومنذ بلوغي -والحمد لله- وهدايتي إلى الطريق المستقيم، فأنا أقوم بالأعمال الصالحة؛ من نوافل، وعبادات، هل يلزمني شيء في ذلك يا سماحة الشيخ؟","title":"هل يحاسب الإنسان على ما كان منه قبل البلوغ؟","answer":"الجواب: الذي قبل البلوغ لا يؤخذ به الإنسان، إنما يؤخذ بما بعد البلوغ، بما كان ما عمل من سيئات قبل البلوغ، لا يؤخذ بها؛ لأنه غير مكلف: كالمجنون، وكالصغير الذي ما بلغ خمسة عشر سنة ما بعد كلف. فالمقصود: أنه لا يؤاخذ إلا بما كان بعد البلوغ بعد التكليف، فالصلاة قبل التكليف، أو سب، أو شتم، أو فعل فاحشة، أو ما أشبه ذلك، كلها لا يؤخذ بها قبل التكليف، لكن ليس له أن يفعل ما حرم الله، ليس له أن يزني، ليس له أن يفعل اللواط، ليس له أن يسرق، ولو كان صغيرًا يؤدب، لكن في الآخرة ما فعله قبل البلوغ لا يؤخذ به، لكن على أوليائه إذا فعل شيئًا قبل البلوغ يؤدبونه إذا رأوه يتعاطى ما حرم الله من لواط.. من سرقات.. من إيذاء لأهله؛ يؤدب، يمنع، وكذلك إذا بلغ عشرًا يؤمر بالصلاة، ويضرب عليها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16175/هل-يحاسب-الانسان-على-ما-كان-منه-قبل-البلوغ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_593/59319.mp3","categories":["مسائل متفرقة في العقيدة","فتاوى متنوعة"]},{"id":17355,"question":"من جمهورية مصر العربية المستمع (م. ن. أ) رسالة وضمنها قضية يقول فيها: أثناء عملي مندوبًا في إحدى الشركات لتوزيع منتجاتها حدث أنني أخطأت ذات يوم مع أحد العملاء للشركة، وأخذت منه ثمن وحدتين من هذه البضاعة زيادة على حساب البضاعة التي أعطيتها له في هذا اليوم، ولم أعرف بذلك، وأثناء توريد الإيراد للشركة وجدت أن معي ثمن وحدتين زيادة عن المطلوب للشركة، وعندما رجعت إلى هذا العميل كالعادة لأعطيه بضاعته قال لي: إنني في المرة الماضية أعطيته البضاعة ناقصة وحدتين، وقلت له: إنني سأعطيك وحدتين ولكن في يوم آخر، وحتى الآن لم أعطه إياها حيث أنني استقلت من الشركة بعدها مباشرة، فماذا أفعل الآن، وأنا أرغب في أن أعطيه نقودًا ثمن تلك الوحدتين إلا أنني لا أعرف مكانه بالضبط، فماذا أفعل؟ جزاكم الله خيرًا.","title":"ما يفعل من أخذ مالًا بالخطأ ولا يعرف مكان صاحبه","answer":"الجواب: عليك أن تتصدق بذلك على الفقراء بالنية عنه، ويكفي، ومتى عرفته بعد حين، وطلبها تخيره، إن شاء قبل الصدقة وصار الأجر له، وإن شاء أعطيته وصار الأجر لك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16234/ما-يفعل-من-اخذ-مالا-بالخطا-ولا-يعرف-مكان-صاحبه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_834/nour_83411.mp3","categories":["مسائل فقهية متفرقة","فتاوى متنوعة"]},{"id":18148,"question":"سماحة الشيخ! تساهل كثير من الأسر في أبنائهم، وهم الحقيقة صغار، ثم يصعب عليهم في الكبر، هل من توجيه؟","title":"توجيه لمن يتساهل في تربية أبنائه","answer":"الجواب: هذا من المصائب العظيمة، التساهل من المصائب العظيمة، والواجب على الأب والأم والإخوة أن لا يتساهلوا في هذا، بل عليهم أن يجتهدوا في توجيه الأبناء والشباب إلى الصلاة، وإلى كل خير، وتحذيرهم مما حرم الله من السب والشتم والعقوق وغيرها من الفواحش والتدخين، وشرب المسكر وغير هذا من المنكرات. ومن أهم شيء بل أهم شيء بعد الشهادتين الصلاة، فعليهم أن يلزموا أولادهم بالصلاة، ويضربوا من تخلف عنها إذا كان بلغ عشرًا فأكثر، هذا هو الواجب على الآباء والأمهات، والإخوة الكبار مع الصغار، هذا من التعاون على البر والتقوى، وقد قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71]، وقال النبي ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان. والوالد مأمور بأن يؤدب أولاده، بالضرب إذا بلغوا عشرًا فأكثر، حتى يستقيموا حتى يصلوا مع الناس.نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وبارك فيكم على هذا التوجيه الطيب المبارك.","link":"https://binbaz.org.sa/fatwas/17188/توجيه-لمن-يتساهل-في-تربية-ابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78116.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":18737,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين بدأها بقوله: نحمد الله  على أن من علينا ببرنامج (نور على الدرب) ونشكر علماءنا الأفاضل، وندعو لهم بالتوفيق والسداد في تبصير الأمة المسلمة بأمور دينها ودنياها، نرجو أن يجيب على هذه الأسئلة سماحة الشيخ عبد العزيز بن باز، مقدم الأسئلة: أبو مؤمن خلف الله علي مصري يعمل باليمن.أخونا يسأل في سؤاله الأول ويقول: سألني أخ مسلم: أين الله؟ فقلت له: في السماء، فقال لي: فما رأيك في قوله تعالى: وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ [البقرة:255] وذكر آيات كثيرة، ثم قال: لو زعمنا أن الله في السماء؛ لحددنا جهة معينة، فما رأي سماحتكم في ذلك؟ وهل هذه الأسئلة من الأمور التي نهينا عن السؤال عنها؟","title":"الدليل على علو الله فوق العرش","answer":"الجواب: قد أصبت في جوابك، وهذا الجواب الذي أجبت به هو الجواب الذي أجاب به النبي -عليه الصلاة والسلام-، فالله -جل وعلا- في السماء، في العلو  كما قال : أَأَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الأَرْضَ فَإِذَا هِيَ تَمُورُ ۝ أَمْ أَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ [الملك:16-17] وقال -جل وعلا-: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] وقال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54]. فهو  فوق العرش في جهة العلو، فوق جميع الخلق، عند جميع أهل العلم من أهل السنة، قد أجمع أهل السنة والجماعة -رحمة الله عليهم- على أن الله في السماء فوق العرش فوق جميع الخلق ، وهذا هو المنقول عن رسول الله ﷺ وعن أصحابه  وعن أتباعهم بإحسان، كما أنه موجود في كتاب الله القرآن. وقد سأل النبي ﷺ جارية جاء بها سيدها ليعتقها، فقال لها الرسول ﷺ: أين الله؟ قالت: في السماء، قال: من أنا؟ قالت: أنت رسول الله، قال: أعتقها، فإنها مؤمنة رواه مسلم في الصحيح، فالرسول ﷺ أقر هذه الجارية على الجواب، الذي قلته أنت، قال لها: أين الله؟ قالت: في السماء، قال: من أنا؟ قالت: أنت رسول الله، قال: أعتقها، فإنها مؤمنة وما ذاك إلا لأن إيمانها بأن الله في السماء يدل على إخلاصها لله، وتوحيدها لله، وأنها مؤمنة به سبحانه، وبعلوه فوق جميع خلقه، وبرسوله محمد -عليه الصلاة والسلام- حيث قالت: أنت رسول الله. \nأما قوله -جل وعلا-: وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ [البقرة:255] هذا لا ينافي ذلك، الكرسي فوق السماوات، والعرش فوق الكرسي، والله فوق العرش، فوق جميع الخلق  وتحديد الجهة لا مانع منه جهة العلو، بأن الله في العلو. وإنما يشبه بهذا بعض المتكلمين وبعض المبتدعة، ويقولون: ليس في جهة، وهذا كلام فيه تفصيل، فإن أرادوا: ليس في جهة مخلوقة، وأنه ليس في داخل السماوات، وليس في داخل الأرض، ونحو هذا صحيح، أما إن أرادوا أنه ليس في العلو، هذا باطل، وهذا خلاف ما دل عليه كتاب الله، وما دلت عليه سنة رسول الله -عليه الصلاة والسلام-، وما دل عليه إجماع سلف الأمة. فقد أجمع علماء الإسلام أن الله في السماء فوق العرش، فوق جميع الخلق، والجهة التي هو فيها جهة العلو، وهي ما فوق جميع الخلق، وهذه الأسئلة ليست بدعة، ولم ننه عنها، بل هذه الأسئلة مأمور بها نعلمها الناس، كما سأل عنها النبي ﷺ قال: أين الله وسأله أبو رزين قال: أين ربنا؟ فأخبره أنه في العلو ، فالله  في العلو في جهة العلو فوق السماوات، فوق العرش، فوق جميع الخلق، وليس في الأرض، ولا في داخل الأرض، ولا في داخل السماوات.    ومن قال: إن الله في الأرض، وأن الله في كل مكان كـالجهمية والمعتزلة ونحوهم فهو كافر عند أهل السنة والجماعة؛ لأنه مكذب لله ولرسوله في إخبارهما بأنه سبحانه في السماء فوق العرش -جل وعلا-، فلا بد من الإيمان بأن الله فوق العرش، فوق جميع الخلق، وأنه في السماء، يعني: في العلو، معنى السماء يعني: العلو، فالسماء يطلق على معنيين: أحدهما: السماوات المبنية، يقال لها: سماء.\nوالثاني: العلو، يقال له: سماء، فالله سبحانه في العلو، في جهة العلو فوق جميع الخلق، وإذا أريد: السماء المبينة المعنى هو: عليها، في يعني: على، في السماء يعني: على السماء وفوقها، كما قال الله سبحانه: فَسِيرُوا فِي الأَرْضِ [آل عمران:137] سيروا في الأرض يعني: عليها فوقها، وكما قال الله  عن فرعون أنه قال: لَأُصَلِّبَنَّكُمْ فِي جُذُوعِ النَّخْلِ [طه:71] يعني: على جذوع النخل، فلا منافاة بين قول من قال: في السماء يعني: على السماء، وبين من قال: إنه في العلو؛ لأن السماء المراد به العلو، فالله في العلو، فوق السماوات فوق جميع الخلق، وفوق العرش . ومن قال: معنى في: على، يعني: أنه فوق السماوات المبنية فوقها، ولا شك أنه فوقها، فوق العرش، فوق جميع الخلق ، فأنت على عقيدة صالحة، وأبشر بالخير، والحمد لله الذي هداك لذلك، ولا تلتفت إلى أقوال المشبهين والملبسين؛ فإنهم في ضلال. وأنت بحمد الله ومن معك على هذه العقيدة أنتم على الحق في إيمانكم بأن الله في السماء، فوق العرش، فوق جميع الخلق ، وعلمه في كل مكان -جل وعلا-، ولا يشابه الخلق في شيء من صفاته ، وليس في حاجة إلى العرش، ولا إلى السماء، بل هو غني عن كل شيء ، والسماوات مفتقرة إليه، والعرش مفتقر أيضًا، وهو الذي أقام العرش، وهو الذي أقام الكرسي، وهو الذي أقام السماوات، وهو الذي أمسكها ، كما قال : وَمِنْ آيَاتِهِ أَنْ تَقُومَ السَّمَاءُ وَالأَرْضُ بِأَمْرِهِ [الروم:25] قال سبحانه: إِنَّ اللَّهَ يُمْسِكُ السَّمَوَاتِ وَالأَرْضَ أَنْ تَزُولا [فاطر:41] فالله الذي أمسك السماوات، وأمسك العرش، وأمسك هذه المخلوقات، فلولا إمساكه لها، وإقامته لها؛ لاندك بعضها على بعض، ولكنه -جل وعلا- هو الذي أقامها وأمسكها حتى يأتي أمر القيامة، فإذا جاء يوم القيامة صار لها حال أخرى. فهو سبحانه على كل شيء قدير، وبكل شيء عليم، وهو العالي فوق جميع خلقه، وصفاته كلها علا، وأسماؤه كلها حسنى، فالواجب على أهل العلم والإيمان أن يصفوا الله سبحانه بما وصف به نفسه، وبما وصفه به رسوله -عليه الصلاة والسلام-، من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، بل مع الإيمان بأنه سبحانه لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17882/الدليل-على-علو-الله-فوق-العرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87509.mp3","categories":["التفسير","الأسماء والصفات","فتاوى متنوعة"]},{"id":19521,"question":"هل من توجيه كريم للآباء والأمهات في توجيه أولادهم في السن المبكرة لتعويدهم على الأمور الشرعية؟","title":"نصيحة للآباء والأمهات بتوجيه الأبناء في الأمور الشرعية","answer":"الجواب: نعم، الواجب على الآباء والأمهات تعليم الأولاد وتوجيههم إلى الخير، تعليم البنين والبنات، وإرشادهم فيما يتعلق بالصوم والصلاة، وما يتعلق بحيض المرأة وغير ذلك، يجب على الأب والأم إرشاد الأولاد يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم:6]، الله جل وعلا أمرهم بهذا.\nوقال ﷺ: كلكم راع وكلكم مسئول عن رعيته، فالرجل راع في أهل بيته ومسئول عن رعيته، والمرأة راعية في بيت زوجها ومسئولة عن رعيتها كلهم راع. فالواجب على الأب أن يعتني بالأولاد وأن يرشدهم، وهكذا الأم، كلهم مسئولون فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ  ۝ عَمَّا كَانُوا يَعْمَلُونَ [الحجر:92، 93]. فالأب يعلم أولاده الذكور والإناث، والأم كذلك حتى ينشئوا على خير وعلى هدى وعلى بصيرة.\nنسأل الله للجميع الهداية. المقدم: اللهم آمين، أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18768/نصيحة-للاباء-والامهات-بتوجيه-الابناء-في-الامور-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93934.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]}]
